'use strict';
(()=>{
 const $=id=>document.getElementById(id),chosen=new Set();const parts={weapon:'무기',head:'머리',chest:'상의',arms:'팔',waist:'허리',legs:'다리',talisman:'호석'};
 const text=(parent,tag,value)=>{const e=document.createElement(tag);e.textContent=value;parent.append(e);return e;};
 const message=s=>$('savedMessage').textContent=s;
 window.saveBuild=(build,name)=>{const entries=SavedBuildStore.get();if(entries.length>=200)throw Error('최대 200개까지 저장할 수 있습니다. 저장 세팅을 정리하세요.');const entry={id:crypto.randomUUID(),name,memo:'',created:Date.now(),build};if(!SavedBuildStore.set([...entries,entry]))throw Error('저장하지 못했습니다. 보유 호석 페이지의 저장 오류를 확인하세요.');return true;};
 function comparison(){const entries=SavedBuildStore.get().filter(e=>chosen.has(e.id)),container=$('savedComparison');container.replaceChildren();if(!entries.length)return;text(container,'h2',`선택한 세팅 비교 · ${entries.length}개`);text(container,'p','금색 행은 선택한 세팅 사이에 차이가 있는 항목입니다. 방어력은 최대 강화 기준입니다. 좁은 화면에서는 표를 좌우로 스크롤하세요.');const wrap=document.createElement('div');wrap.className='table-wrap';const table=document.createElement('table'),head=document.createElement('thead'),tr=document.createElement('tr');text(tr,'th','항목');for(const e of entries)text(tr,'th',e.name);head.append(tr);table.append(head);const body=document.createElement('tbody');
 const row=(label,values)=>{const tr=document.createElement('tr');if(new Set(values).size>1)tr.className='comparison-difference';const th=text(tr,'th',label);th.scope='row';for(const value of values)text(tr,'td',value);body.append(tr);};
 row('최대 강화 방어력',entries.map(e=>String(e.build.defense)));for(const [key,label]of [['fire','불'],['water','물'],['thunder','번개'],['ice','얼음'],['dragon','용']])row('기본 '+label+' 내성',entries.map(e=>e.build.resistances?.[key]===undefined?'미기록':String(e.build.resistances[key])));for(const[part,label]of Object.entries(parts).filter(([p])=>p!=='talisman'))row(label,entries.map(e=>{const a=e.build.equipment.find(a=>a.part===part);return a.name+' ['+(a.slots.join('/')||'없음')+']';}));
 row('무기 부여 시리즈·그룹 스킬',entries.map(e=>(e.build.weaponBonuses||[]).map(b=>b.name+' · 1부위').join(' / ')||'없음'));
 row('호석',entries.map(e=>{const c=e.build.charm;return c?c.skills.map(s=>s.name+' Lv.'+s.level).join(' / ')+` · 무기 ${c.weaponSlots.join('/')||'없음'} · 방어구 ${c.armorSlots.join('/')||'없음'}`:'사용 안 함';}));
 const skills=[...new Set(entries.flatMap(e=>e.build.skills.map(s=>s.name)))].sort((a,b)=>a.localeCompare(b,'ko'));for(const name of skills)row(name,entries.map(e=>'Lv.'+(e.build.skills.find(s=>s.name===name)?.level||0)));
 row('발동 세트·그룹 효과',entries.map(e=>e.build.bonuses.map(b=>`${b.name}: ${b.effect} (${b.pieces}부위)`).join(' / ')||'없음'));
 row('장식주 배치',entries.map(e=>e.build.decorations.map(d=>`${parts[d.owner]} ${d.index+1}번 ${d.kind==='weapon'?'무기':'방어구'}[${d.size}]: ${d.name}`).join('\n')||'없음'));
 row('목표 스킬',entries.map(e=>e.build.goals.map(g=>`${g.name} Lv.${g.required}`).join(' / ')));row('데이터 반영 버전',entries.map(e=>e.build.source));table.append(body);wrap.append(table);container.append(wrap);}
 function render(){const entries=SavedBuildStore.get(),container=$('savedList');for(const id of chosen)if(!entries.some(e=>e.id===id))chosen.delete(id);container.replaceChildren();if(!entries.length){text(container,'h2','아직 저장한 세팅이 없습니다.');text(container,'p','세팅 검색 결과에서 ‘이 세팅 저장’을 누르세요.');const b=text(container,'button','세팅 검색으로');b.dataset.route='build';}for(const e of [...entries].reverse()){const card=document.createElement('article');card.className='build-card saved-card';text(card,'h2',e.name);text(card,'p',`방어력 ${e.build.defense} · ${new Date(e.created).toLocaleString('ko-KR')}`);text(card,'p',e.build.goals.map(g=>`${g.name} Lv.${g.level}`).join(' / '));if(e.memo)text(card,'p',e.memo);const label=document.createElement('label');label.className='compare-choice';const check=document.createElement('input');check.type='checkbox';check.checked=chosen.has(e.id);check.addEventListener('change',()=>{if(check.checked&&chosen.size>=3){check.checked=false;message('한 번에 최대 3개를 비교할 수 있습니다.');return;}if(check.checked)chosen.add(e.id);else chosen.delete(e.id);message('');comparison();});label.append(check,document.createTextNode('비교에 포함'));card.append(label);
 const details=document.createElement('details');text(details,'summary','장비·장식주 상세');for(const a of e.build.equipment)text(details,'p',`${parts[a.part]}: ${a.name} · 슬롯 ${a.slots.join('/')||'없음'}`);text(details,'p','무기 부여 스킬: '+((e.build.weaponBonuses||[]).map(b=>b.name+' · 1부위').join(' / ')||'없음'));text(details,'p','호석: '+(e.build.charm?e.build.charm.skills.map(s=>`${s.name} Lv.${s.level}`).join(' / ')+` · 무기 ${e.build.charm.weaponSlots.join('/')||'없음'} · 방어구 ${e.build.charm.armorSlots.join('/')||'없음'}`:'사용 안 함'));for(const d of e.build.decorations)text(details,'p',`${parts[d.owner]} ${d.index+1}번 ${d.kind==='weapon'?'무기':'방어구'}[${d.size}]: ${d.name}`);text(details,'p','스킬: '+e.build.skills.map(s=>s.name+' Lv.'+s.level).join(' / '));text(details,'p','발동 효과: '+(e.build.bonuses.map(b=>`${b.name}: ${b.effect} (${b.pieces}부위)`).join(' / ')||'없음'));if(e.build.resistances)text(details,'p','방어구 기본 내성: '+[['fire','불'],['water','물'],['thunder','번개'],['ice','얼음'],['dragon','용']].map(([key,label])=>`${label} ${e.build.resistances[key]}`).join(' / '));text(details,'p','MHDB 반영 버전: '+e.build.source);card.append(details);
 const form=document.createElement('form');form.className='saved-edit';const nameLabel=text(form,'label','세팅 이름'),name=document.createElement('input');name.value=e.name;name.required=true;name.maxLength=80;nameLabel.append(name);const memoLabel=text(form,'label','메모'),memo=document.createElement('textarea');memo.value=e.memo;memo.maxLength=1000;memo.rows=2;memoLabel.append(memo);const actions=document.createElement('div');actions.className='actions';const update=text(actions,'button','이름·메모 저장');update.type='submit';const remove=text(actions,'button','세팅 삭제');remove.type='button';remove.className='danger';remove.addEventListener('click',()=>{if(confirm(`‘${e.name}’ 세팅을 삭제할까요?`)){if(SavedBuildStore.set(SavedBuildStore.get().filter(x=>x.id!==e.id)))message('세팅을 삭제했습니다.');else message('삭제하지 못했습니다. 저장 상태를 확인하세요.');}});form.append(actions);form.addEventListener('submit',event=>{event.preventDefault();const n=name.value.trim();if(!n){message('세팅 이름을 입력하세요.');return;}if(SavedBuildStore.set(SavedBuildStore.get().map(x=>x.id===e.id?{...x,name:n,memo:memo.value}:x)))message('이름과 메모를 저장했습니다.');else message('저장하지 못했습니다. 다른 탭 변경이나 저장 공간을 확인하세요.');});card.append(form);container.append(card);}comparison();}
 $('savedPage').addEventListener('page-enter',()=>{message('');render();});document.addEventListener('inventory-state-changed',()=>{if(!$('savedPage').hidden)render();});
})();
